(7171047, 1100307, 61396, '<td valign="top">very nice. <br/> <br/>(technically: good handling of the shadows, however, the light on the new you seems to come from the wrong direction)</td>', 'very nice.  (technically: good handling of the shadows, however, the light on the new you seems to come from the wrong direction)', '2014-02-06 17:18:15.000000', NULL, 1),
